<?php
/** Admin-only manual commands: changes selected content or visibility on the website after opt-in. */
$pageTitle='ویرایش محدود خدمات و تیم سایت'; require_login(); header('Cache-Control: no-store');
require_once __DIR__.'/../includes/site_content_commands.php';
require_once __DIR__.'/../includes/site_content_lookup.php';
$me=(int)($_SESSION['user_id'] ?? 0);
try { $st=$pdo->prepare('SELECT status,role FROM users WHERE id=?'); $st->execute([$me]); $actor=$st->fetch(PDO::FETCH_ASSOC);
    if (!is_strict_admin() || !$actor || $actor['status']!=='active' || $actor['role']!=='admin') { http_response_code(403); echo 'دسترسی مجاز نیست.'; return; }
} catch (Throwable $e) { http_response_code(503); echo 'بررسی دسترسی ممکن نیست.'; return; }
$readonly=is_nazer_kol() || (!access_is_special_account() && access_mode('crm_customers')==='viewer');
$configured=content_command_configured(true); $ready=false;
if ($configured) $ready=crm_content_command_ensure($pdo);
else { try { $pdo->query('SELECT 1 FROM crm_site_content_commands LIMIT 1'); $ready=true; } catch (Throwable $e) {} }
$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES | ENT_SUBSTITUTE,'UTF-8');
$modes=['service'=>'خدمت فارسی','service_en'=>'خدمت انگلیسی','team'=>'نام و نقش عضو تیم','team_profile'=>'شناسه و معرفی عضو تیم'];
$firstLabels=['service'=>'عنوان فارسی','service_en'=>'عنوان انگلیسی','team'=>'نام','team_profile'=>'شناسه نمایشی'];
$secondLabels=['service'=>'توضیح فارسی','service_en'=>'توضیح انگلیسی','team'=>'نقش','team_profile'=>'معرفی'];
$optionalModes=['service_en','team_profile'];
$visibilityModes=['service_visibility'=>'وضعیت خدمت','team_visibility'=>'وضعیت عضو تیم'];
$orderModes=['service_order'=>'ترتیب خدمت','team_order'=>'ترتیب عضو تیم'];
$structuredModes=$visibilityModes+$orderModes;
$createModes=['service_create'=>'خدمت','team_create'=>'عضو تیم'];
$preview=null; $baseline=null; $lookup=null; $listing=null; $inspected=null; $notice='';
if (($_SERVER['REQUEST_METHOD'] ?? '')==='POST') {
    try {
        $action=$_POST['action'] ?? null; $kind=$_POST['kind'] ?? null; $rawId=$_POST['object_id'] ?? null; $token=$_POST['token'] ?? null;
        if ($readonly || !is_string($action)) throw new DomainException('درخواست یا پیکربندی معتبر نیست.');
        if (in_array($action,['inspect','stop','resume','resolve'],true)) {
            $commandId=$_POST['command_id'] ?? null;
            if (!$ready || !is_string($commandId) || !preg_match('/^[a-f0-9]{32}$/D',$commandId)) throw new DomainException('فرمان معتبر نیست.');
            if ($action==='inspect') {
                $st=$pdo->prepare('SELECT * FROM crm_site_content_commands WHERE command_id=?'); $st->execute([$commandId]); $r=$st->fetch(PDO::FETCH_ASSOC);
                if (!$r) throw new DomainException('فرمان یافت نشد.');
                $body=(string)$r['payload']; $c=json_decode($body,true);
                if (strlen($body)>8192 || !is_string($r['payload_hash']) || !hash_equals($r['payload_hash'],hash('sha256',$body)) || !content_command_validate($c,(string)$r['source_id']) || $c['command_id']!==$r['command_id'] || content_command_kind($c)!==$r['kind'] || $c['actor_id']!==(int)$r['actor_id']) throw new DomainException('محتوای فرمان ناسازگار است؛ نتیجه و داده را مستقل بررسی کنید.');
                $isCreated=in_array(content_command_mode($c),['service_create','team_create'],true) && $r['state']==='applied';
                if ((!$isCreated && $c['object_id']!==(int)$r['object_id']) || ($isCreated && ((int)$r['object_id']<=0 || (int)$r['object_id']>4294967295))) throw new DomainException('شناسهٔ فرمان ناسازگار است.');
                $inspected=['id'=>$commandId,'mode'=>content_command_mode($c),'object_id'=>(int)$r['object_id'],'state'=>$r['state'],'attempts'=>(int)$r['attempts'],'fields'=>$c['fields'],'issued_at'=>$c['issued_at'],'expires_at'=>$c['expires_at']];
            } else {
                crm_content_command_transition($pdo,$me,true,$commandId,$action,time(),($_POST['confirm_check'] ?? null)==='1' && ($_POST['confirm_risk'] ?? null)==='1');
                showToast('وضعیت محلی فرمان ثبت شد؛ نتیجهٔ سایت را مستقل بررسی کنید.'); redirect('index.php?page=site_content_commands');
            }
        } else {
        if (!in_array($action,['list','lookup','preview','enqueue','create_preview','create_enqueue'],true) || !is_string($kind) || !in_array($kind,['service','service_en','team','team_profile','service_visibility','team_visibility','service_order','team_order','service_create','team_create'],true)) throw new DomainException('درخواست یا پیکربندی معتبر نیست.');
        $isCreate=isset($createModes[$kind]);
        if ($isCreate) {
            if (!in_array($action,['create_preview','create_enqueue'],true) || !$ready || !$configured || !content_command_kind_enabled($kind)) throw new DomainException('ایجاد این نوع فعال یا آماده نیست.');
            $first=$_POST['first'] ?? null; $second=$_POST['second'] ?? null;
            if (!is_string($first) || !is_string($second)) throw new DomainException('متن معتبر نیست.');
            $fields=$kind==='service_create'?['title_fa'=>$first,'description_fa'=>$second]:['name'=>$first,'role'=>$second];
            $now=time(); $probe=['type'=>content_command_type($kind),'command_id'=>str_repeat('a',32),'source_id'=>SITE_CONTENT_COMMAND_SOURCE_ID,'object_id'=>0,'actor_id'=>$me,'expected_token'=>'','issued_at'=>$now,'expires_at'=>$now+900,'fields'=>$fields];
            if (!content_command_validate($probe,SITE_CONTENT_COMMAND_SOURCE_ID)) throw new DomainException('متن نامعتبر است؛ فاصلهٔ ابتدا/انتها مجاز نیست.');
            if ($action==='create_preview') $preview=['kind'=>$kind,'first'=>$first,'second'=>$second];
            else {
                crm_content_command_enqueue($pdo,$me,true,$kind,0,'',$fields,$now,($_POST['confirm_identity'] ?? null)==='1' && ($_POST['confirm_change'] ?? null)==='1');
                showToast('فرمان ایجاد در صف ثبت شد؛ هنوز تضمینی برای ایجاد نیست.'); redirect('index.php?page=site_content_commands');
            }
        } elseif (in_array($action,['create_preview','create_enqueue'],true)) throw new DomainException('نوع درخواست معتبر نیست.');
        elseif ($action==='list') {
            $after=$_POST['after_id'] ?? null;
            if (!content_lookup_configured(true) || !content_lookup_list_enabled($kind) || !is_string($after) || !preg_match('/^(0|[1-9][0-9]{0,17})$/D',$after)) throw new DomainException('صفحهٔ فهرست معتبر نیست.');
            $listing=crm_content_lookup_list_fetch($kind,(int)$after);
        } elseif (!is_string($rawId) || !preg_match('/^[1-9][0-9]{0,17}$/D',$rawId)) throw new DomainException('شناسه معتبر نیست.');
        if ($isCreate) { /* Handled above; creation never performs a lookup. */ }
        elseif ($action==='lookup') {
            $lookup=crm_content_lookup_fetch($kind,(int)$rawId);
            if (!$lookup['found']) { $lookup=null; throw new DomainException('رکورد در سایت یافت نشد؛ هویت و منبع را دوباره بررسی کنید.'); }
        } elseif ($action!=='list') {
            if (!$ready || !$configured || !content_command_kind_enabled($kind) || !is_string($token)) throw new DomainException('درخواست یا پیکربندی معتبر نیست.');
            $isVisibility=isset($visibilityModes[$kind]); $isOrder=isset($orderModes[$kind]);
            if ($isOrder) {
                $desiredOrder=$_POST['desired_order'] ?? null;
                if (!content_lookup_order_valid($desiredOrder)) throw new DomainException('ترتیب باید عدد صحیح معتبر باشد.');
                $fields=['display_order'=>(int)$desiredOrder];
            } elseif ($isVisibility) {
                $desired=$_POST['desired_active'] ?? null;
                if (!is_string($desired) || !in_array($desired,['0','1'],true)) throw new DomainException('وضعیت مطلوب را انتخاب کنید.');
                $fields=['is_active'=>(int)$desired];
            } else {
                $first=$_POST['first'] ?? null; $second=$_POST['second'] ?? null; if (!is_string($first) || !is_string($second)) throw new DomainException('متن معتبر نیست.');
                $fields=$kind==='service'?['title_fa'=>$first,'description_fa'=>$second]:($kind==='service_en'?['title_en'=>$first,'description_en'=>$second]:($kind==='team_profile'?['handle'=>$first,'bio'=>$second]:['name'=>$first,'role'=>$second]));
            }
            $now=time(); $probe=['type'=>content_command_type($kind),'command_id'=>str_repeat('a',32),'source_id'=>SITE_CONTENT_COMMAND_SOURCE_ID,'object_id'=>(int)$rawId,'actor_id'=>$me,'expected_token'=>$token,'issued_at'=>$now,'expires_at'=>$now+900,'fields'=>$fields];
            if (!content_command_validate($probe,SITE_CONTENT_COMMAND_SOURCE_ID)) throw new DomainException('متن، شناسه یا نسخه معتبر نیست؛ فاصلهٔ ابتدا/انتها مجاز نیست.');
            if ($isVisibility || $isOrder || ($action==='preview' && ($_POST['compare'] ?? null)==='1')) {
                if (!content_lookup_matches_command() || !content_lookup_kind_enabled($kind)) throw new DomainException('دریافت و فرمان به منبع یکسان متصل نیستند یا غیرفعال‌اند.');
                $baseline=crm_content_lookup_fetch($kind,(int)$rawId);
                if (!$baseline['found'] || !hash_equals($baseline['token'],$token)) { $baseline=null; throw new DomainException('رکورد سایت تغییر کرده یا موجود نیست؛ دوباره دریافت و بررسی کنید.'); }
            }
            if ($action==='preview') {
                $preview=$isOrder?['kind'=>$kind,'object_id'=>$rawId,'token'=>$token,'desired_order'=>$desiredOrder]:($isVisibility?['kind'=>$kind,'object_id'=>$rawId,'token'=>$token,'desired_active'=>$desired]:['kind'=>$kind,'object_id'=>$rawId,'token'=>$token,'first'=>$first,'second'=>$second]);
            } else {
                crm_content_command_enqueue($pdo,$me,true,$kind,(int)$rawId,$token,$fields,$now,($_POST['confirm_identity'] ?? null)==='1' && ($_POST['confirm_change'] ?? null)==='1');
                showToast('فرمان در صف ثبت شد؛ هنوز تضمینی برای تغییر سایت نیست.'); redirect('index.php?page=site_content_commands');
            }
        }
        }
    } catch (Throwable $e) { error_log('Content command request failed: '.get_class($e)); $notice=$e instanceof DomainException?$e->getMessage():'ثبت فرمان ممکن نیست.'; }
}
$rows=[]; if ($ready) { try { $st=$pdo->query('SELECT command_id,kind,object_id,actor_id,state,created_at,completed_at,payload FROM crm_site_content_commands ORDER BY created_at DESC,command_id DESC LIMIT 30'); $rows=$st->fetchAll(PDO::FETCH_ASSOC); } catch (Throwable $e) { $ready=false; } }
include 'includes/header.php';
?>
<div class="page-header"><h1>ویرایش محدود خدمات و تیم سایت</h1><p>این قابلیت آزمایشی است: فقط عنوان و توضیح فارسی یا انگلیسی خدمت یا نام و نقش یا شناسه نمایشی و معرفی عضو موجود را تغییر می‌دهد؛ با مجوز مستقل می‌تواند برچسب فعال یا ترتیب خدمت یا عضو را نیز عوض کند. ایجاد محدود به‌صورت غیرفعال اختیاری است؛ حذف، تصویر، ایمیل و پیوند شبکه انجام نمی‌شود. دو سامانه مستقل می‌مانند.</p></div>
<div class="card" style="padding:16px"><p><strong>برای شناسایی صحیح، رکورد سایت را مستقل بررسی کنید. فعال‌کردن ممکن است آن را در سایت عمومی نمایش دهد و غیرفعال‌کردن ممکن است آن را پنهان کند؛ برچسب فعال اثبات نمایش نیست. دریافت اختیاری فقط دو فیلد را در همان لحظه نشان می‌دهد و هنگام پیش‌نمایش دوباره بررسی می‌شود؛ در روش دستی باید نسخه را از پنل سایت کپی کنید. سایت هنگام اجرای فرمان نسخه را دوباره می‌سنجد. تغییر و بازگشت، استفادهٔ مجدد شناسه یا تغییر بعدی ممکن است شناسایی نشوند؛ داده و نسخه اثبات هویت نیستند.</strong></p>
<p>برای انگلیسی خدمت و شناسه/معرفی عضو، مقدار NULL هنگام دریافت خالی نمایش داده می‌شود و ذخیرهٔ متن خالی به رشتهٔ خالی تبدیلش می‌کند، نه NULL. شناسه و معرفی عضو ممکن است دادهٔ شخصی باشد. برای ایجاد، تکراری‌نبودن باید مستقل بررسی شود؛ شناسه پس از رسید موفق نمایش داده می‌شود. متن فرمان‌ها در CRM و بکاپ آن باقی می‌ماند؛ نام اعضای تیم می‌تواند اطلاعات شخصی باشد. هر فرمان ۱۵ دقیقه اعتبار دارد؛ دریافت گمشده نتیجه را نامعلوم می‌کند. applied فقط نتیجهٔ لحظهٔ اجراست، نه وضعیت فعلی. پنل قدیمی تا تطبیق و آزمون کامل حفظ شود.</p>
