<?php if ($isCreate): ?><h3>پیش‌نمایش ایجاد <?= $h($createModes[$preview['kind']]) ?> غیرفعال</h3><p><strong><?= $h($preview['first']) ?></strong></p><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?= $h($preview['second']) ?></pre><p>این عملیات در سایت رکورد جدید می‌سازد؛ وجود نداشتن رکورد مشابه، هویت و عدم انتشار را مستقل بررسی کنید. پاسخ گمشده نتیجه را نامعلوم می‌کند و ارسال فرمان تازه ممکن است رکورد تکراری بسازد.</p>
<?php elseif ($isOrder): ?><h3>مقایسهٔ ترتیب سایت و ترتیب پیشنهادی</h3><p>نوع: <?= $h($orderModes[$preview['kind']]) ?> — شناسه سایت <?= $h($preview['object_id']) ?></p><p>نام/عنوان دریافت‌شده: <strong><?= $h($baseline['first']) ?></strong></p><p>ترتیب فعلی: <strong><?= $h($baseline['second']) ?></strong> — ترتیب پیشنهادی: <strong><?= $h($preview['desired_order']) ?></strong></p><p>ترتیب ممکن است در قالب عمومی مؤثر باشد؛ مقدار و نام اثبات هویت یا نمایش نیستند.</p>
<?php elseif ($isVisibility): ?><h3>مقایسهٔ وضعیت سایت و وضعیت پیشنهادی</h3><p>نوع: <?= $h($visibilityModes[$preview['kind']]) ?> — شناسه سایت <?= $h($preview['object_id']) ?></p><p>نام/عنوان دریافت‌شده: <strong><?= $h($baseline['first']) ?></strong></p><p>برچسب فعلی: <strong><?= $baseline['second']==='1'?'فعال':'غیرفعال' ?></strong> — برچسب پیشنهادی: <strong><?= $preview['desired_active']==='1'?'فعال':'غیرفعال' ?></strong></p><p>فعال کردن ممکن است رکورد را در سایت عمومی نمایش دهد؛ این پیش‌نمایش یا برچسب، اثبات هویت یا نمایش نیست.</p>
<?php else: ?><h3><?= $baseline?'مقایسه دو فیلد دریافت‌شده از سایت با متن جدید':'پیش‌نمایش متن جدید (بدون مقایسه با سایت)' ?></h3><?php if ($baseline): ?><p>مقادیر سایت در زمان پیش‌نمایش دریافت شده‌اند؛ ممکن است بعداً تغییر کنند.</p><h4>دو فیلد فعلی سایت</h4><p><strong><?= $h($baseline['first']) ?></strong></p><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?= $h($baseline['second']) ?></pre><h4>مقادیر پیشنهادی جدید</h4><?php endif; ?><p>نوع: <?= $h($modes[$preview['kind']]) ?> — شناسه سایت <?= $h($preview['object_id']) ?></p><p><strong><?= $h($preview['first']) ?></strong></p><pre style="white-space:pre-wrap;overflow-wrap:anywhere"><?= $h($preview['second']) ?></pre><?php endif; ?>
<form method="post" onsubmit="return confirm('این فرمان ممکن است سایت عمومی را تغییر دهد. ارسال شود؟');"><?= get_csrf_field() ?><input type="hidden" name="action" value="<?= $isCreate?'create_enqueue':'enqueue' ?>"><?php foreach ($preview as $k=>$v): ?><input type="hidden" name="<?= $h($k) ?>" value="<?= $h($v) ?>"><?php endforeach; ?>
<label><input type="checkbox" name="confirm_identity" value="1" required> <?= $isCreate?'تکراری نبودن و هویت رکورد پیشنهادی را مستقل بررسی کردم.':'شناسه، نسخه و هویت رکورد فعلی را مستقل بررسی کردم.' ?></label><br><label><input type="checkbox" name="confirm_change" value="1" required> <?= $isCreate?'می‌دانم یک رکورد جدید غیرفعال در سایت ساخته می‌شود و بعداً ممکن است منتشر شود.':'تغییر پیشنهادی را بررسی کردم و می‌دانم ممکن است سایت عمومی تغییر کند.' ?></label><br><button class="btn" type="submit">ثبت فرمان برای ارسال</button></form><?php endif; ?>
<?php if (!$readonly && content_lookup_configured(true)): foreach (['service'=>'خدمات','team'=>'اعضای تیم'] as $listKind=>$listLabel): if (!content_lookup_list_enabled($listKind)) continue; ?>
